package ui11_pkg;
 import uvm_pkg::*;`include "uvm_macros.svh"
 class ui11_item extends uvm_sequence_item;`uvm_object_utils(ui11_item)int id,payload;function new(string n="i");super.new(n);endfunction endclass
 class ui11_burst_sequence extends uvm_sequence#(ui11_item);`uvm_object_utils(ui11_burst_sequence)int first_id,first_payload,item_count=3;function new(string n="b");super.new(n);endfunction task body();ui11_item req;for(int i=0;i<item_count;i++)begin req=ui11_item::type_id::create("req");start_item(req);req.id=first_id+i;req.payload=first_payload+i;finish_item(req);end endtask endclass
 class ui11_composite_sequence extends uvm_sequence#(ui11_item);`uvm_object_utils(ui11_composite_sequence)int subsequences_completed;function new(string n="c");super.new(n);endfunction task body();ui11_burst_sequence a,b;a=ui11_burst_sequence::type_id::create("a");a.first_id=0;a.first_payload=10;a.item_count=3;a.start(m_sequencer,this);subsequences_completed++;b=ui11_burst_sequence::type_id::create("b");b.first_id=3;b.first_payload=20;b.item_count=3;b.start(m_sequencer,this);subsequences_completed++;endtask endclass
 class ui11_sequencer extends uvm_sequencer#(ui11_item);`uvm_component_utils(ui11_sequencer)function new(string n,uvm_component p);super.new(n,p);endfunction endclass
 class ui11_driver extends uvm_driver#(ui11_item);`uvm_component_utils(ui11_driver)int completed;function new(string n,uvm_component p);super.new(n,p);endfunction task run_phase(uvm_phase phase);ui11_item req;int ep;for(int i=0;i<6;i++)begin seq_item_port.get_next_item(req);if(i<3)ep=10+i;else ep=17+i;if((req.id!=i)||(req.payload!=ep))`uvm_fatal("UI11_ORDER","wrong item")completed++;seq_item_port.item_done();end endtask endclass
 class ui11_env extends uvm_env;`uvm_component_utils(ui11_env)ui11_sequencer sequencer;ui11_driver driver;function new(string n,uvm_component p);super.new(n,p);endfunction function void build_phase(uvm_phase phase);super.build_phase(phase);sequencer=ui11_sequencer::type_id::create("sequencer",this);driver=ui11_driver::type_id::create("driver",this);endfunction function void connect_phase(uvm_phase phase);driver.seq_item_port.connect(sequencer.seq_item_export);endfunction endclass
 class ui11_test extends uvm_test;`uvm_component_utils(ui11_test)ui11_env env;function new(string n,uvm_component p);super.new(n,p);endfunction function void build_phase(uvm_phase phase);super.build_phase(phase);env=ui11_env::type_id::create("env",this);endfunction task run_phase(uvm_phase phase);ui11_composite_sequence s;uvm_report_server rs;int e,f;phase.raise_objection(this);s=ui11_composite_sequence::type_id::create("s");s.start(env.sequencer);rs=uvm_report_server::get_server();e=rs.get_severity_count(UVM_ERROR);f=rs.get_severity_count(UVM_FATAL);if((env.driver.completed!=6)||(s.subsequences_completed!=2)||(e!=0)||(f!=0))`uvm_fatal("UI11_VERDICT","bad")$display("SEQUENCE_TRACE: completed=6 subsequences=2 errors=0 fatals=0");$display("TEST_RESULT: PASS");phase.drop_objection(this);endtask endclass
endpackage
